package com.example.customers.domain;

import java.text.Normalizer;
import java.util.ArrayList;
import java.util.List;
import java.util.Locale;
import java.util.Set;

/**
 * A filter that narrows down customer queries on the backend side.
 *
 * <p>The name filter consists of terms...
 */
public record CustomerFilter(List<String> nameTerms, Set<CustomerStatus> statuses) {

    public CustomerFilter {
        nameTerms = List.copyOf(nameTerms);
        statuses = Set.copyOf(statuses);
    }

    /** A filter that matches all customers. */
    public static CustomerFilter none() {
        return new CustomerFilter(List.of(), Set.of());
    }

    /**
     * Parses a raw name filter into normalized terms.
     *
     * <p>The raw text is split on whitespace and each term is normalized so that
     * matching can ignore case and accents (in both directions):
     * {@code makinen}, {@code MAKINEN} and {@code mäkinen} all normalize to the
     * same term. Empty and whitespace-only names produce no terms, which means
     * every customer matches.
     */
    public static CustomerFilter of(String rawName, Set<CustomerStatus> statuses) {
        List<String> terms = new ArrayList<>();
        if (rawName != null) {
            for (String term : rawName.trim().split("\\s+")) {
                if (!term.isEmpty()) {
                    terms.add(normalize(term));
                }
            }
        }
        return new CustomerFilter(terms, statuses == null ? Set.of() : statuses);
    }

    /** Normalizes a string so comparisons can ignore case and accents. */
    public static String normalize(String value) {
        return Normalizer.normalize(value, Normalizer.Form.NFKD)
                .replaceAll("\\p{M}", "")
                .toLowerCase(Locale.ROOT);
    }

    /** True when the filter does not narrow the data set at all. */
    public boolean isEmpty() {
        return nameTerms.isEmpty() && statuses.isEmpty();
    }
}
```

