+package com.example.customers.domain;
+
+import java.text.Normalizer;
+import java.util.ArrayList;
+import java.util.List;
+import java.util.Locale;
+import java.util.Set;
+
+/**
+ * A filter that narrows customer queries in the backend.
+ *
+ * <p>The name filter is a list of terms: a customer matches when <b>every</b>
+ * term occurs as a substring of the customer's first name or last name. Terms
+ * are normalized on creation, so matching ignores case and accents in both
+ * directions: {@code makinen}, {@code MAKINEN} and {@code mäkinen} are the same
+ * term. A filter without name terms matches every customer.
+ *
+ * <p>The status filter is a set of {@link CustomerStatus values}: with nothing
+ * selected every status matches, otherwise the customer must have one of the
+ * selected statuses.
+ *
+ * @param nameTerms normalized name terms, in the order they were entered
+ * @param statuses  selected statuses, empty for "all statuses"
+ */
+public record CustomerFilter(List<String> nameTerms, Set<CustomerStatus> statuses) {
+
+    public CustomerFilter {
+        nameTerms = List.copyOf(nameTerms);
+        statuses = Set.copyOf(statuses);
+    }
+
+    /** A filter that matches every customer. */
+    public static CustomerFilter none() {
+        return new CustomerFilter(List.of(), Set.of());
+    }
+
+    /**
+     * Parses a raw name filter into a {@link CustomerFilter}.
+     *
+     * <p>The raw text is split on whitespace into terms; leading, trailing and
+     * repeated whitespace is not significant. Each term is normalized with
+     * {@link #normalize(String)}. An empty or whitespace-only name produces no
+     * terms, which matches every customer.
+     *
+     * @param rawName the text the user typed into the name field, may be null
+     * @param statuses the selected statuses, may be null for none
+     */
+    public static CustomerFilter of(String rawName, Set<CustomerStatus> statuses) {
+        List<String> terms = new ArrayList<>();
+        if (rawName != null) {
+            for (String term : rawName.trim().split("\\s+")) {
+                if (!term.isEmpty()) {
+                    terms.add(normalize(term));
+                }
+            }
+        }
+        return new CustomerFilter(terms, statuses == null ? Set.of() : statuses);
+    }
+
+    /**
+     * Normalizes a string so that comparisons ignore case and accents:
+     * {@code "Mäkinen"}, {@code "MAKINEN"} and {@code "mäkinen"} all normalize
+     * to {@code "makinen"}.
+     */
+    public static String normalize(String value) {
+        return Normalizer.normalize(value, Normalizer.Form.NFKD)
+                .replaceAll("\\p{M}", "")
+                .toLowerCase(Locale.ROOT);
+    }
+
+    /** True when the filter does not narrow the data set at all. */
+    public boolean isEmpty() {
+        return nameTerms.isEmpty() && statuses.isEmpty();
+    }
+}
