+        for (int i = 1; i <= name.length(); i++) {
+            _setValue(nameField(), name.substring(0, i));
+        }
+
+        // Let the debounced update fire and flush the grid's re-fetch.
+        flushUntil(2_000, () -> summary().getText().equals("Showing 15 of 500"));
+        assertEquals("Virtanen", _get(grid(), 0).lastName());
+
+        int pageQueries = queryLog.pageQueries().size();
+        assertTrue(pageQueries <= 2,
+                "Typing a " + name.length() + "-letter name ran " + pageQueries
