+    /**
+     * Polls {@code condition} until it holds or {@code timeoutMillis} pass,
+     * driving a client round trip on every iteration so that pending grid
+     * re-fetches (triggered by the debounced update) are flushed.
+     */
+    private void flushUntil(long timeoutMillis, java.util.function.BooleanSupplier condition)
+            throws InterruptedException {
+        long deadline = System.currentTimeMillis() + timeoutMillis;
+        while (!condition.getAsBoolean()) {
+            if (System.currentTimeMillis() > deadline) {
+                throw new AssertionError("Condition not met within " + timeoutMillis + " ms");
+            }
+            MockVaadin.clientRoundtrip();
+            TimeUnit.MILLISECONDS.sleep(25);
+        }
+    }
